import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"鼎","description":"焦氏易林注 - 鼎","frontmatter":{"title":"鼎","description":"焦氏易林注 - 鼎"},"headers":[],"relativePath":"classics/jiaoyilin/050.md","filePath":"classics/jiaoyilin/050.md"}'),l={name:"classics/jiaoyilin/050.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="鼎" tabindex="-1">鼎 <a class="header-anchor" href="#鼎" aria-label="Permalink to “鼎”">​</a></h1><h3 id="鼎-1" tabindex="-1">鼎 <a class="header-anchor" href="#鼎-1" aria-label="Permalink to “鼎”">​</a></h3><h3 id="鼎之乾" tabindex="-1">鼎之乾 <a class="header-anchor" href="#鼎之乾" aria-label="Permalink to “鼎之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>傾筐捲耳，憂不能傷。心思古人，悲慕失母。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《鼎》象。伏震為筐，坎為耳、為憂、為心、為悲慕，坤為母。捲耳，草名，《周南》&quot;採採捲耳，不盈傾筐&quot;，《毛傳》謂后妃思君子不在，茲謂失母，與毛異。○古，宋元本作故，依汲古。</p><h3 id="鼎之坤" tabindex="-1">鼎之坤 <a class="header-anchor" href="#鼎之坤" aria-label="Permalink to “鼎之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>卻叔賈貸，行祿多悔，利無所得。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍用《鼎》象。巽為退，伏艮為叔，故曰卻叔。震為商賈、為行、為路，坤為悔，巽為利，坤亡，故無得。晉卻氏貪而好貸，數世不改，至成公十七年果為厲公所滅，故林詞云云。</p><h3 id="鼎之屯" tabindex="-1">鼎之屯 <a class="header-anchor" href="#鼎之屯" aria-label="Permalink to “鼎之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>蹶足狂跛，怪碎不行。棄捐乎人，名字無申。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為足，坎蹇，故曰蹶、曰跛。坎為怪、為破，坤閉，艮止，故不行。坤為棄捐。震為人，艮為名，坤為文字。坤黑，坎伏，故曰無申。申，明也。○首二句宋元本作&quot;蹙狂跛衽，闢坐不行&quot;，捐乎作損平，申作中，均依汲古。</p><h3 id="鼎之蒙" tabindex="-1">鼎之蒙 <a class="header-anchor" href="#鼎之蒙" aria-label="Permalink to “鼎之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>文王四乳，仁愛篤厚。子畜十男，夭折無有。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>見前《頤》之《節》。</p><h3 id="鼎之需" tabindex="-1">鼎之需 <a class="header-anchor" href="#鼎之需" aria-label="Permalink to “鼎之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>容民蓄眾，不離其居。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為眾、為民，伏艮為居。○居，汲古作君，依宋元本。</p><h3 id="鼎之訟" tabindex="-1">鼎之訟 <a class="header-anchor" href="#鼎之訟" aria-label="Permalink to “鼎之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>三雛相逐，蠅墜釜中。灌沸淹殪，與母長決。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>伏震為子、為行，故曰三雛相逐。巽為蠅，伏坤為釜、為水、為死、為母。○雛，宋元本作摧。按：《訟彖》&quot;不利涉大川，入於淵也&quot;，故林詞如此。</p><h3 id="鼎之師" tabindex="-1">鼎之師 <a class="header-anchor" href="#鼎之師" aria-label="Permalink to “鼎之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>所望在外，鼎令方來。拭爵滌罍，灼食待之，不為季憂。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>此兼用《鼎》象。離在外卦，故曰所望在外。震為鼎、為爵、為罍，伏艮，故曰拭爵。坎水，故曰滌罍。艮為待、為季。○滌，宋元作澡，依汲古。又鼎令疑為鼎命，即大命也。</p><h3 id="鼎之比" tabindex="-1">鼎之比 <a class="header-anchor" href="#鼎之比" aria-label="Permalink to “鼎之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>陸居少泉，高山無雲。車行千里，塗汙爾輪，亦為我患。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎為泉，坤艮皆為陸，故曰少泉。坎為雲，艮為高山，坎隱伏，故無雲。坤為車、為千里，坎為輪、為泥塗，故曰塗汙爾輪。坎為患。</p><h3 id="鼎之小畜" tabindex="-1">鼎之小畜 <a class="header-anchor" href="#鼎之小畜" aria-label="Permalink to “鼎之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>東家殺牛，聞臭腥臊。神背西顧，命衰絕周。亳社災燒，宋人夷誅。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《巽》。聞，汲古本作汙，依宋元本。西，宋元本作不，依汲古。衰絕，汲古作絕衰，非，依宋元。神背西顧，言背東家而西顧也。命衰絕周，言殷命已衰，而絕於周室也。</p><h3 id="鼎之履" tabindex="-1">鼎之履 <a class="header-anchor" href="#鼎之履" aria-label="Permalink to “鼎之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>長子入獄，婦饋母哭。霜降旬日，嚮晦伏法。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>旁通《謙》。震為長子，坎為獄，坤為母，伏巽為入、為婦，兌口，故曰母哭。坤為霜，離日，坤數十，故曰旬日。坤為晦、為殺，故曰伏法。《隋書刑法志》：&quot;聖王莫不先春風而播恩，後秋霜而動憲&quot;，是自古殺人皆在霜降後，茲曰嚮晦，並用晦日也。</p><h3 id="鼎之泰" tabindex="-1">鼎之泰 <a class="header-anchor" href="#鼎之泰" aria-label="Permalink to “鼎之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>溫山松柏，常茂不落。鳳凰以庇，得其歡樂。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《坤》。</p><h3 id="鼎之否" tabindex="-1">鼎之否 <a class="header-anchor" href="#鼎之否" aria-label="Permalink to “鼎之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>大屋之下，朝多君子。德施溥育，宋受其福。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為屋，上乾，故曰大屋。艮為朝、為君子，坤眾，故曰多。《說文》&quot;以木架屋曰宋&quot;，故艮為宋。○溥，宋元本作博，依汲古。</p><h3 id="鼎之同人" tabindex="-1">鼎之同人 <a class="header-anchor" href="#鼎之同人" aria-label="Permalink to “鼎之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>羅張目抉，圍合耦缺，魚鳥生脫。離為網羅、為目。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>抉決通。兌毀，故目決，言網目毀也。離中虛，故曰圍合。二人為耦，按：《周禮天官》掌次射則張耦次。疏：凡射耦，皆兩兩俱升南面而射，耦缺則射者無。巽寡，故曰耦缺。巽為魚，離為鳥，目抉耦缺，故魚鳥得脫也。○抉，汲古訛列，耦作月，多採捕無功四字，在第三句，俱依宋元本。</p><h3 id="鼎之大有" tabindex="-1">鼎之大有 <a class="header-anchor" href="#鼎之大有" aria-label="Permalink to “鼎之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>羔裘豹袪，高易我宇。君子維好，至老無憂。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，離文為豹，乾為衣，故曰羔裘豹袪。伏艮為高、為宇、為君子。乾為老，坤為憂，坤伏，故不憂。羔裘，《唐風》篇名，毛謂晉人不恤其民，刺詩茲雲君子無憂，與毛異。○宇，元本訛字，依宋本。第四句宋元本無，依汲古。</p><h3 id="鼎之謙" tabindex="-1">鼎之謙 <a class="header-anchor" href="#鼎之謙" aria-label="Permalink to “鼎之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>大頭明目，載受嘉福。三雀飛來，與祿相得。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坎為大首，伏離為明目，震為載、為嘉福。數三，艮為雀，故曰三雀。○嘉福，宋元本作喜福，汲古更訛為福善，依周［當作局］本。</p><h3 id="鼎之豫" tabindex="-1">鼎之豫 <a class="header-anchor" href="#鼎之豫" aria-label="Permalink to “鼎之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>銷鋒鑄耜，休放牛馬。甲兵解散，夫婦相保。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》林。第二句宋元本作縱牛救馬，汲古作縱牛放馬，依晉林校。又耜宋元本訛刃。</p><h3 id="鼎之隨" tabindex="-1">鼎之隨 <a class="header-anchor" href="#鼎之隨" aria-label="Permalink to “鼎之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>吉日車攻，田弋獵禽。反行飲至，以告嘉功。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《夬》。車攻，宋元本作舉釣，依汲古。獵，汲古作雙，反行飲至作宣王飲酒，均依宋元本。嘉，宋元本訛喜，依汲古。</p><h3 id="鼎之蠱" tabindex="-1">鼎之蠱 <a class="header-anchor" href="#鼎之蠱" aria-label="Permalink to “鼎之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>商人行旅，資無所有。貪貝逐利，留連王市。轘轅內安，公子何咎。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為商旅，艮為貝，巽為利，艮止，故曰留連。巽為市，震為王，故曰王市。震為轅、為公子，艮為安。按：《左傳襄二十二年》：欒盈被掠於周，周王使候出諸轘轅。又《高祖紀》因張良遂掠韓地轘轅。是轘轅為地名，而《管子》雲：凡主兵者必先審知地圖，轘轅之險。又《東京賦》：邪徑捷乎轘轅，薛綜註：轘轅，十二曲道，將去復還，故曰轘轅。是轘轅為曲徑，所以設險，故曰轘轅內安，公子無咎。蓋艮震皆為道路，卦三至上艮震相反覆像轘轅也。○王市，宋元本作玉帛，轘作馭，均依汲古。</p><h3 id="鼎之臨" tabindex="-1">鼎之臨 <a class="header-anchor" href="#鼎之臨" aria-label="Permalink to “鼎之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>火入井口，揚芒生角。犯歷天門，窺觀太微。登上玉床，家易其公。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>通《遯》。艮為星、為火，兌為井、為口，艮為角。火，熒惑也，言熒惑入井。艮為門，上乾為天，《內經》以戊亥為天門，乾艮皆位西北，故曰天門。艮為觀，《天文志》太微為五帝之庭，明堂之房。乾為帝、為玉，艮為床，故曰玉床。艮為家，震為公，言熒惑入井，芒角犯太微，國君將易也。○首句宋元本作火井暘谷，依汲古。揚，汲古作陽，依宋元本。其，宋元本作共，又有作六者，依汲古。此自古星佔，顧炎武謂林詞本《漢書李尋傳》，《李尋傳》焉有火入井口之語，先儒從不知林詞皆本卦象，故誤解。</p><h3 id="鼎之觀" tabindex="-1">鼎之觀 <a class="header-anchor" href="#鼎之觀" aria-label="Permalink to “鼎之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>秋隼冬翔，數被嚴霜。甲兵充庭，萬物不生。雞釜夜鳴，民擾大驚。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>通《大壯》。兌為秋，艮為隼，乾為冬，震為翔，故曰秋隼冬翔。坤為霜，艮為甲兵、為庭，坤為萬物，坤殺，故不生。巽為雞，坤為釜、為夜，震為鳴，故曰雞釜夜鳴。坤為民，震為驚。釜鳴，詳《復》之《旅》。雞夜鳴，言失時也。</p><h3 id="鼎之噬嗑" tabindex="-1">鼎之噬嗑 <a class="header-anchor" href="#鼎之噬嗑" aria-label="Permalink to “鼎之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>東行西步，失其次舍。乾侯野井，昭君喪居。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為東行，坎西，故曰西步。艮為次舍。震為諸侯、為君，上離，故曰乾侯、曰昭君。艮為野，伏兌為井，《左傳昭三十二年》公薨於乾侯。野井，齊地名。昭二十五年齊侯唁公於野井是也。</p><h3 id="鼎之賁" tabindex="-1">鼎之賁 <a class="header-anchor" href="#鼎之賁" aria-label="Permalink to “鼎之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>腫脛病腹，陷廁汙辱。命短時極，孤子哀哭。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為脛，艮為節，故曰腫脛。腫，《說文》癰也。離為腹，互坎，故曰病腹。坎為廁、為陷、為汙，艮為時，伏巽為命，兌為折，故曰短命。震為子，坎孤，坎悲，故曰孤子哀哭。伏兌為哭。《左傳》晉侯有疾，張，如廁，陷而卒。</p><h3 id="鼎之剝" tabindex="-1">鼎之剝 <a class="header-anchor" href="#鼎之剝" aria-label="Permalink to “鼎之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>切膚近火，虎絕我須。小人橫暴，君子何之。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為膚、為火、為虎、為須、為君子，坤為小人，重坤，陰盛銷陽，故曰橫暴。艮止，坤閉，故曰何之。○火，汲古作災，之亦作災，依宋元本。子，宋元本作復，非，依汲古。</p><h3 id="鼎之復" tabindex="-1">鼎之復 <a class="header-anchor" href="#鼎之復" aria-label="Permalink to “鼎之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>女室作毒，為我心疾。和不能治，晉人赴告。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為女、為室、為毒、為心、為疾，《左傳昭元年》女陽物也，而晦時淫，則生內惑蠱之疾，故曰女室作毒，為我心疾。坤死，故和不能治。震為晉、為人、為告，言平公死，赴告列國也。○不，汲古作弗，非。劉毓崧雲：弗，昭帝名。易林諱當時君名，故不見弗字。果，宋元本皆作不。</p><h3 id="鼎之無妄" tabindex="-1">鼎之無妄 <a class="header-anchor" href="#鼎之無妄" aria-label="Permalink to “鼎之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>兵徵大宛，北出玉門。與胡寇戰，平城道西。七日絕糧，身幾不全。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》林。此以巽為寇，餘象皆同。</p><h3 id="鼎之大畜" tabindex="-1">鼎之大畜 <a class="header-anchor" href="#鼎之大畜" aria-label="Permalink to “鼎之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>九子十夫，莫適與居。貞心不壹，自令老孤。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震數九，故曰九子。震為夫，兌數十，故曰十夫。艮為居，正反艮，故曰莫適與居、曰貞心不壹。艮為貞，乾為老，伏巽為寡，故曰孤。○首句汲古訛十子夬九，壹訛宣，自令老孤訛至今名孤，均依宋元本。</p><h3 id="鼎之頤" tabindex="-1">鼎之頤 <a class="header-anchor" href="#鼎之頤" aria-label="Permalink to “鼎之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>車行稻麥，遂至家國。樂土無災，君子何憂。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為車、為稻麥，坤為家國、為土、為災、為憂，震為樂、為解，故無災憂。○子，宋元本作父，車作東，均依汲古。車行者，言以車運行稻麥至家也。</p><h3 id="鼎之大過" tabindex="-1">鼎之大過 <a class="header-anchor" href="#鼎之大過" aria-label="Permalink to “鼎之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>作室山根，所以為安。一夕崩顛，破我饔飧。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《明夷》。</p><h3 id="鼎之坎" tabindex="-1">鼎之坎 <a class="header-anchor" href="#鼎之坎" aria-label="Permalink to “鼎之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>六人俱行，各遺其囊。黃鵠失珠，無以為明。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《師》。</p><h3 id="鼎之離" tabindex="-1">鼎之離 <a class="header-anchor" href="#鼎之離" aria-label="Permalink to “鼎之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>伯蹇叔盲，莫為守囊。失我衣裘，不離其鄉。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏坎。中爻震為伯，坎蹇，故曰伯蹇。艮為叔，中爻互大離，故曰叔盲，故曰囊。艮守，坎伏，故莫為守囊。震為衣裘，上下坎，故曰失。艮為鄉也。○鄉，汲古作邦，依宋元本。此句各本皆作我是、陰鄉或陰邦，我是者失我之訛，陰鄉尤難解，今從《否》之《噬嗑》校。</p><h3 id="鼎之鹹" tabindex="-1">鼎之鹹 <a class="header-anchor" href="#鼎之鹹" aria-label="Permalink to “鼎之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>襃寵灑尤，敗政傾家。覆我宗國，秦滅周室。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>互乾為王，巽為母，有王母之象，故曰襃。襃，幽王后，襃姒也。伏坤為尤。灑尤者，言龍灑於王庭也。伏坤為政，艮為家室、為國，兌毀，故曰敗傾。艮為國，震為宗，震覆為艮，故曰覆我宗國。兌為秦，震為周，震伏，故曰秦滅周室。《詩》：&quot;赫赫宗周，襃姒滅之&quot;，林詠其事。○灑，汲古作溢，依宋元本。</p><h3 id="鼎之恆" tabindex="-1">鼎之恆 <a class="header-anchor" href="#鼎之恆" aria-label="Permalink to “鼎之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>詭言譯語，仇禍相得。冰入炭室，消滅不息。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>伏正反震，故曰詭言譯語。伏坤為仇、為禍、為冰，艮為室、為火，火與坤連，故曰冰入炭室。坤消坤死，故曰不息。○詭，宋元本作該，非，依汲古。</p><h3 id="鼎之遯" tabindex="-1">鼎之遯 <a class="header-anchor" href="#鼎之遯" aria-label="Permalink to “鼎之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>彭生為豕，暴龍作災。盜堯衣裳，聚蹠荷兵。青禽照夜，三日夷亡。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《蒙》。此以巽為豕、為盜、為蹠，首句宋元本作彭名為妖，汲古作彭生為妖，依《比》之《蒙》校。</p><h3 id="鼎之大壯" tabindex="-1">鼎之大壯 <a class="header-anchor" href="#鼎之大壯" aria-label="Permalink to “鼎之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>朝露白日，四馬過隙。歲短期促，時難再得。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為朝、為白，兌為露，乾為日、為馬，震卦數四，故曰四馬。伏巽為隙，乾為歲，伏艮為時期，伏觀為消卦，故曰歲短期促也。《漢書張良傳》人生如白駒過隙。</p><h3 id="鼎之晉" tabindex="-1">鼎之晉 <a class="header-anchor" href="#鼎之晉" aria-label="Permalink to “鼎之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>耳闕道喪，所為不成，求事匪得。伏坎，故耳闕。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為道，道喪，言無耳喪失人道也。艮為求，坤為事，坤喪，故所為不成，求事不得也。○喪，宋元本作衰，依汲古。求事，汲古作所求，依宋元本。</p><h3 id="鼎之明夷" tabindex="-1">鼎之明夷 <a class="header-anchor" href="#鼎之明夷" aria-label="Permalink to “鼎之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>申公患楚，危不自安。重耳出奔，側喪其魂。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為申、為楚，坎為患危，坤為重，故曰子重。耳訛字。震為出奔、為子，坎為邪，故曰側。側，子反名也。乾為魂，乾伏，故曰喪魂，坤為喪也。《左傳成七年》子重請取於申呂以為賞，子反欲取夏姬，皆為申公巫臣所止，後巫臣自取夏姬，奔晉，故子重子反皆怨巫臣而滅其族。巫臣遺二子書曰：餘必使爾疲於奔命以死，後巫臣教吳伐楚，子重子反於是乎一歲七奔命。重耳為子重之訛，然各本皆如此，不敢改也。</p><h3 id="鼎之家人" tabindex="-1">鼎之家人 <a class="header-anchor" href="#鼎之家人" aria-label="Permalink to “鼎之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>南上太山，困於空桑。左沙右石，牛馬無食。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《鼎》象。伏震為南，艮為山，坎為困，巽為桑，離枯，故曰空桑。震左，兌右，艮為沙，巽為石，故曰左沙右石。離牛，乾馬，兌為食，離虛，故無食。○空，宋元本作此，依汲古。</p><h3 id="鼎之睽" tabindex="-1">鼎之睽 <a class="header-anchor" href="#鼎之睽" aria-label="Permalink to “鼎之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>悔隅遼右，福祿所在。柔嘉蒙禮，九夷何咎。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>兌為海、為右，伏艮為東北，故曰遼右。遇卦鼎，乾為福祿。伏坤為柔、為禮，震為嘉，數九，故曰九夷，坤為夷也。《論語》子欲居九夷。</p><h3 id="鼎之蹇" tabindex="-1">鼎之蹇 <a class="header-anchor" href="#鼎之蹇" aria-label="Permalink to “鼎之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>陽春生長，萬物壯茂。垂枝布葉，君子比德。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此仍用《鼎》象。伏震為陽春、為生長、為壯茂，伏坤為萬物、為枝葉，艮為君子，震為德。○枝，汲古訛秋，依宋元本。</p><h3 id="鼎之解" tabindex="-1">鼎之解 <a class="header-anchor" href="#鼎之解" aria-label="Permalink to “鼎之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>低頭竊視，有所畏避。行作不利，酒酸魚敗，眾莫貪嗜。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎為首、為，故曰低頭。離為視，坎盜，故曰竊視。坎為畏，坎隱伏，故曰畏避。坎險，故曰不利。坎為酒菜，伏巽為魚，巽木，木曲作酸，故曰酒酸。巽為臭，故曰魚敗。坎為眾。○作，宋元本訛伯，莫訛若，均依汲古。</p><h3 id="鼎之損" tabindex="-1">鼎之損 <a class="header-anchor" href="#鼎之損" aria-label="Permalink to “鼎之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>左輔右弼，金玉滿堂。常盈不亡，富如敖倉。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《歸妹》。堂，宋元本作櫃，如作於，均依汲古。</p><h3 id="鼎之益" tabindex="-1">鼎之益 <a class="header-anchor" href="#鼎之益" aria-label="Permalink to “鼎之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>坐朝垂軒，據德宰民。虞叔受命，六合和親。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為坐，坤為朝、為軒、為民，震為德，艮手，故曰據德。艮官，故曰宰民。震為驩虞，艮為叔，故曰虞叔。巽為命，坤為合，伏乾數六，故曰六合，言虞舜坐朝堂為天子也。</p><h3 id="鼎之夬" tabindex="-1">鼎之夬 <a class="header-anchor" href="#鼎之夬" aria-label="Permalink to “鼎之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>東行西坐，喪其犬馬。南求驊騮，失車林下。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用《鼎》象。伏震為東、為行，伏坎為西，艮為坐，故曰西坐。艮犬，震馬，坤喪，故曰喪其犬馬。震為南、為馬，艮為求，故曰南求，故曰南求驊騮。坤為輿，震為林，坎失，故曰失車林下。坤為下也。○坐，汲古作走，依宋元本。</p><h3 id="鼎之姤" tabindex="-1">鼎之姤 <a class="header-anchor" href="#鼎之姤" aria-label="Permalink to “鼎之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>砥德礪材，果當成周。拜受大命，封為齊侯。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>此亦用《鼎》象。伏震為德、為材，艮為石，故曰砥礪。艮為果，震為周，艮為成，故曰果當成周。艮為拜，本卦巽為命，重乾，故曰大命。巽為齊，震為諸侯，故曰齊侯。果當成周者，言太公積德，果遇文王也。</p><h3 id="鼎之萃" tabindex="-1">鼎之萃 <a class="header-anchor" href="#鼎之萃" aria-label="Permalink to “鼎之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>西逢王母，慈我九子。相對歡喜，王孫萬戶，家蒙福祉。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>兌在西，坤母，伏乾，故曰王母。伏震為子，數九，坤為慈，故曰慈我九子。伏象正反震相對，故曰相對歡喜。艮為孫，伏震為王，故曰王孫。坤為戶、為萬，故曰萬戶。艮為家，伏震為福祉。</p><h3 id="鼎之升" tabindex="-1">鼎之升 <a class="header-anchor" href="#鼎之升" aria-label="Permalink to “鼎之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>安坐玉床，聽韶行觴。飲福萬歲，曰壽無疆。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>伏艮為坐，震為玉，巽為床，故曰玉床。震為樂、為觴，兌為耳，故曰聽韶行觴。震為福、為萬歲，兌口，故曰飲。伏艮為壽，坤廣，故曰無疆。○曰，宋元本作日，依汲古。</p><h3 id="鼎之困" tabindex="-1">鼎之困 <a class="header-anchor" href="#鼎之困" aria-label="Permalink to “鼎之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>登高望家，役事未休。王事靡盬，不得逍遙。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》之《解》。○事，宋元本作政，依汲古。</p><h3 id="鼎之井" tabindex="-1">鼎之井 <a class="header-anchor" href="#鼎之井" aria-label="Permalink to “鼎之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>擊鼓蹈陔，不得相逾。章甫文德，福厭禍消。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>元刊註雲：陔，階次也。按：禮有陔夏，樂有擊鼓，為登階之節，故曰不得相逾，言登階有節，不得亂也。伏震為鼓，艮為擊、為陔、為冠，故曰章甫。伏離為文，震為福，坎為禍。厭，足也。○蹈，汲古作陷，非。消，宋本作涓，依元本、汲古。</p><h3 id="鼎之革" tabindex="-1">鼎之革 <a class="header-anchor" href="#鼎之革" aria-label="Permalink to “鼎之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>追亡逐北，至山而復。稚叔相呼，反其室廬。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>依《需》之《渙》校。各本皆作&quot;追亡逐北，呼還幼叔。至山而復，得反其室&quot;。</p><h3 id="鼎之鼎" tabindex="-1">鼎之鼎 <a class="header-anchor" href="#鼎之鼎" aria-label="Permalink to “鼎之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>積德之君，仁政且溫。伊呂股肱，國富民安。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>伏《屯》。震為德、為君、為仁，坤為積、為政、為國、為民、為富，震為伊，巽為呂、為股肱。○君，宋元本作至，仁作君，依汲古。</p><h3 id="鼎之震" tabindex="-1">鼎之震 <a class="header-anchor" href="#鼎之震" aria-label="Permalink to “鼎之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>老滑大，東行盜珠。困於噬敖，幾不得去。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>《山海經》雲：堯光之山有獸穴居而冬蟄，名曰猾餘。峩之山有獸焉，見人則眠，名曰狳。狳，即也。皆艮象。震為東、為珠，坎為盜，故曰盜珠。坎為困。噬敖，按《詩》搏獸於敖《傳》：敖，地名。噬敖，疑亦地名也。○，宋元本訛偷，珠作敖，均依汲古。困，汲古作國，依宋元本。</p><h3 id="鼎之艮" tabindex="-1">鼎之艮 <a class="header-anchor" href="#鼎之艮" aria-label="Permalink to “鼎之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>禹召諸神，會稽南山。執玉萬國，天下康安。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《臨》。神，宋元本作侯，第二句作南山會稽，均依汲古。安，汲古作寜，依宋元本。</p><h3 id="鼎之漸" tabindex="-1">鼎之漸 <a class="header-anchor" href="#鼎之漸" aria-label="Permalink to “鼎之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>忉忉怛怛，如將不活。黍稷之恩，靈輒以存，獲生保年。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《損》。首句宋元本作忉怛忉怛，茲依汲古。</p><h3 id="鼎之歸妹" tabindex="-1">鼎之歸妹 <a class="header-anchor" href="#鼎之歸妹" aria-label="Permalink to “鼎之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>侯叔興起，季子富有。照臨楚國，蠻荊是安。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>元刊註：季氏富於周公，然下曰照臨楚國，則上二句皆楚事也。按：《左傳文元年》楚成王欲立商臣為太子，令尹子上曰：楚國之舉，恆在少者，言楚君恆為少子也。又昭十三年叔向曰：棄疾必有楚國，羋姓有亂，必季實立楚之常也。首二句言楚之興起，富有者恆在叔季之子，與子上叔向語同也。《左傳昭七年》薳啟強曰：將使衡父照臨楚國。震為侯、為興起、為荊楚，伏艮為叔季、為安。○侯，宋本作俟，依元本。</p><h3 id="鼎之豐" tabindex="-1">鼎之豐 <a class="header-anchor" href="#鼎之豐" aria-label="Permalink to “鼎之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>白馬駿騮，更生不休。富我商人，利得如丘。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。震為白、為馬，故曰白馬駿騮。震為生，二五正反震，故曰更生不休。震為商人，艮為丘，巽為利。○駿騮，宋元本作駁，依汲古。</p><h3 id="鼎之旅" tabindex="-1">鼎之旅 <a class="header-anchor" href="#鼎之旅" aria-label="Permalink to “鼎之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>灼火泉源，釣魴山顛。魚不可得，炭不肯然。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《艮》。</p><h3 id="鼎之巽" tabindex="-1">鼎之巽 <a class="header-anchor" href="#鼎之巽" aria-label="Permalink to “鼎之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>避患東西，反入禍門。糟糠不足，憂動我心。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《需》。</p><h3 id="鼎之兌" tabindex="-1">鼎之兌 <a class="header-anchor" href="#鼎之兌" aria-label="Permalink to “鼎之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>成王多寵，商臣惶恐。生其禍心，使君危殆。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏艮為成，震為王，兌為媚、為姬，重兌，故曰多寵。震為商，艮為臣，坎為恐、為心、為禍、為危殆。震為君。○成，汲古作我，形訛字。臣作人，聲訛字。成，依宋元本，臣，依元本。宋本亦訛人。君，汲古作我，依宋元本。汲古多終無災咎四字，宋元本無。商臣，楚成王世子，後弒成王，見《左傳文元年》。</p><h3 id="鼎之渙" tabindex="-1">鼎之渙 <a class="header-anchor" href="#鼎之渙" aria-label="Permalink to “鼎之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>虎飢欲食，見蝟而伏。禹通龍門，避咎除患，元醜以安。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，伏離，中虛，故曰飢。伏兌為食，坎為棘、為蝟、為隱伏。《史記龜策傳》註：蝟能伏虎，言虎將食，見蝟而畏伏。震為龍，艮為門，震為帝王，故曰禹。孟氏逸象坤為醜，此似以坎為醜。○飢，宋元本作飲，依汲古。患，汲古作禍，依宋元本。</p><h3 id="鼎之節" tabindex="-1">鼎之節 <a class="header-anchor" href="#鼎之節" aria-label="Permalink to “鼎之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>按民呼池，玉杯文案。魚如白雲，一邑獲願。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>杯者，杖之訛。《後漢書禮儀志》：仲秋縣道按戶比民，年七十者，授以玉杖。八十九十，禮有加。文案，蓋養老加禮也。坎為民、為池，艮為按。震為玉、為椀、為案。案，椀也。伏離，故曰文。伏巽，故曰魚、曰白。坎為雲，故曰白雲。艮為邑，坎數一，故曰一邑。此亦有故事，為今所不能考。牟庭等便謂呼池改為安民縣在平帝二年，為焦氏所不及見，疑為崔篆所為，豈知安為按之訛字。《同人》之《豫》宋本、元本、汲古皆作按呼，汲古且作湖，安得據此訛字，以致疑乎。多見其不考耳。丁晏卿謂牟庭私改按為安，雖未必然，然按民呼池與安民呼池義孰為優，可不煩言而解，乃牟氏故作安民縣解，固可疑也。○首句各本皆作安民呼池，依《同人》之《豫》校。文，汲古作大，依宋元本。魚，元本、汲古作泉，雲作蜜，皆形訛字，依宋本。邑，汲古作挹，乃後人妄改，以就泉蜜之訛，依宋元本。</p><h3 id="鼎之中孚" tabindex="-1">鼎之中孚 <a class="header-anchor" href="#鼎之中孚" aria-label="Permalink to “鼎之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>雙鳧鴛鴦，相隨群行。南至饒澤，食魚與粱，君子樂長。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，正反艮故曰雙鳧、曰鴛鴦、曰群行。震為行、為南，兌為澤、為食，巽為魚、為稻粱。艮為君子，震為樂，巽為長。○群，宋元本訛君，樂作與，茲依汲古。</p><h3 id="鼎之小過" tabindex="-1">鼎之小過 <a class="header-anchor" href="#鼎之小過" aria-label="Permalink to “鼎之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>蔡侯朝楚，留連江渚。逾時歷月，思其君後。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《坤》。詳《豫》之《坤》。</p><h3 id="鼎之既濟" tabindex="-1">鼎之既濟 <a class="header-anchor" href="#鼎之既濟" aria-label="Permalink to “鼎之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>膠車駕東，與雨相逢。五楘解墮，頹杌獨坐，憂為身禍。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《蠱》。楘、墮，元本作棨、墜。頹杌，宋本作頓厄，元本作頹輈，茲依汲古。</p><h3 id="鼎之未濟" tabindex="-1">鼎之未濟 <a class="header-anchor" href="#鼎之未濟" aria-label="Permalink to “鼎之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>螟蟲為賊，害我稼穡。盡禾殫麥，秋無所得。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《節》。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
